  place-items: center;
  flex-shrink: 0;
  width: 34px;
  height: 34px;
  border-radius: var(--radius-md);
  background: rgba(251, 191, 36, 0.18);
  color: var(--text-warning);
}

.dup-banner-text { flex: 1; min-width: 200px; }
.dup-banner-text strong { display: block; font-size: var(--fs-md); margin-bottom: 0.15rem; }

.dup-banner-text p {
  margin: 0;
  font-size: var(--fs-base);
  line-height: 1.5;
