}

/* ---------- Elegant: serif, centred, hairlines. Jewellers and clinics. ---------- */
.inv-tpl-elegant {
  font-family: Georgia, 'Times New Roman', 'Noto Serif', serif;
}

.inv-tpl-elegant .inv-ribbon {
  height: 2.5mm;
  background: var(--inv-accent-deep);
}

.inv-tpl-elegant .inv-ribbon::after {
  display: none;
}

.inv-tpl-elegant .inv-head {
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 3mm;
  border-bottom: 1px solid var(--inv-accent-line);
}

.inv-tpl-elegant .inv-brand {
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 2mm;
}

.inv-tpl-elegant .inv-shop-name {
  font-size: 24px;
  letter-spacing: 0.02em;
}

.inv-tpl-elegant .inv-contact,
.inv-tpl-elegant .inv-idents {
  justify-content: center;
}

.inv-tpl-elegant .inv-address {
  max-width: 120mm;
}

.inv-tpl-elegant .inv-doc {
  text-align: center;
  width: 100%;
  min-width: 0;
}

.inv-tpl-elegant .inv-doc-type {
  background: none;
  color: var(--inv-accent-deep);
  border-top: 1px solid var(--inv-accent-line);
  border-bottom: 1px solid var(--inv-accent-line);
  border-radius: 0;
  padding: 1mm 6mm;
  letter-spacing: 0.32em;
  font-weight: 600;
}

.inv-tpl-elegant .inv-doc-meta {
  width: auto;
  margin: 2.5mm auto 0;
}

.inv-tpl-elegant .inv-doc-meta th {
  padding-right: 2mm;
  text-align: right;
}

.inv-tpl-elegant .inv-doc-meta td {
  text-align: left;
}

.inv-tpl-elegant .inv-items thead th {
  background: transparent;
  color: var(--inv-ink);
  border-top: 1px solid var(--inv-ink-faint);
  border-bottom: 1px solid var(--inv-ink-faint);
  font-weight: 600;
  letter-spacing: 0.14em;
}

.inv-tpl-elegant .inv-items tbody tr:nth-child(even) td {
  background: transparent;
}

.inv-tpl-elegant .inv-items tbody td {
  border-bottom: 1px solid var(--inv-rule);
}

.inv-tpl-elegant .inv-items tfoot td {
  background: transparent;
  border-top: 1px solid var(--inv-ink-faint);
  border-bottom: 1px solid var(--inv-ink-faint);
}

.inv-tpl-elegant .inv-party,
.inv-tpl-elegant .inv-block {
  border: none;
  border-top: 1px solid var(--inv-accent-line);
  border-radius: 0;
  background: transparent;
  padding-left: 0;
  padding-right: 0;
}

.inv-tpl-elegant .inv-grand {
  background: transparent;
  color: var(--inv-ink);
  border-top: 1.5px solid var(--inv-accent-deep);
  border-bottom: 1.5px solid var(--inv-accent-deep);
  border-radius: 0;
}

.inv-tpl-elegant .inv-grand strong {
  font-size: 22px;
  color: var(--inv-accent-deep);
}

.inv-tpl-elegant .inv-strip {
  background: transparent;
  border-top: 1px solid var(--inv-accent-line);
  border-radius: 0;
}

/* ---------- Compact: roughly twice the lines per page ---------- */
.inv-tpl-compact {
  padding: 9mm 9mm 7mm;
  font-size: 9.5px;
}

.inv-tpl-compact .inv-watermark {
  display: none;
}

.inv-tpl-compact .inv-ribbon {
  height: 3.5mm;
}

.inv-tpl-compact .inv-head {
  padding-bottom: 2.2mm;
  margin-bottom: 2.2mm;
  gap: 5mm;
}

.inv-tpl-compact .inv-logo {
  width: 13mm;
  height: 13mm;
}

.inv-tpl-compact .inv-shop-name {
  font-size: 16px;
}

.inv-tpl-compact .inv-doc-type {
  font-size: 11px;
  padding: 0.9mm 3mm;
}

.inv-tpl-compact .inv-parties {
  gap: 2.5mm;
  margin-bottom: 2.5mm;
}

.inv-tpl-compact .inv-party {
  padding: 1.8mm 2.4mm;
}

.inv-tpl-compact .inv-items thead th {
  padding: 1.3mm 1.6mm;
}

.inv-tpl-compact .inv-items tbody td {
  padding: 1mm 1.6mm;
}

.inv-tpl-compact .inv-items tfoot td {
  padding: 1.3mm 1.6mm;
}

.inv-tpl-compact .inv-block {
  margin-bottom: 2mm;
  padding: 1.6mm 2.2mm;
}

.inv-tpl-compact .inv-lower {
  gap: 3.5mm;
  margin-bottom: 2.5mm;
}

.inv-tpl-compact .inv-foot {
  min-height: 22mm;
  padding-top: 2mm;
}

.inv-tpl-compact .inv-sign-space {
  height: 11mm;
}

.inv-tpl-compact .inv-grand strong {
  font-size: 17px;
}

/* ---------- Pre-printed letterhead: get out of the way of the shop's own paper -- */
.inv-tpl-letterhead .inv-ribbon,
.inv-tpl-letterhead .inv-brand,
.inv-tpl-letterhead .inv-watermark {
  display: none;
}

.inv-tpl-letterhead {
  padding-top: 40mm;
}

.inv-tpl-letterhead .inv-head {
  justify-content: flex-end;
  border-bottom-width: 1px;
}

/* Screen-only reminder of what that emptiness is for — it must never print, or the
   shop's own letterhead ends up with a dashed box drawn over it. */
@media screen {
  .inv-tpl-letterhead::before {
    content: 'PRE-PRINTED LETTERHEAD AREA';
    position: absolute;
    top: 6mm;
    left: 12mm;
    right: 12mm;
    height: 28mm;
    display: flex;
    align-items: center;
    justify-content: center;
    border: 1px dashed var(--inv-rule-strong);
    border-radius: 2mm;
    color: var(--inv-ink-faint);
    font-size: 9px;
    font-weight: 700;
    letter-spacing: 0.16em;
    z-index: 3;
  }
}

/* ---------- Receipt & Restaurant: the bill a hotel actually hands over ----------
   Two layouts taken off real Pune restaurant bills a shopkeeper sent us — a dot-matrix
   canteen slip and a modern hotel bill. Both are *receipt-shaped*: one centred column,
   no colour fills, no boxed cards, the grand total sitting immediately under the items
   with a rule above and below it, and "thank you, visit again" centred at the foot.

   They are page layouts like every other template here — the same markup, the same
   numbers. What they change is that a page stops pretending to be a filing document and
   starts reading like the slip a customer is handed across a counter. On A4 and A5 the
   sheet keeps its size but the content is set in a narrow centred column, because a
   receipt stretched across 186mm is not a receipt.

   `Receipt` is the dot-matrix one: monospace, dashed rules, spaced-out title.
   `Restaurant` is the printed one: bold centred name, solid rules, sentence-case heads. */

/* ---- Shared receipt shape ---- */
.inv-tpl-receipt .inv-ribbon,
.inv-tpl-receipt .inv-watermark,
.inv-tpl-restaurant .inv-ribbon,
.inv-tpl-restaurant .inv-watermark {
  display: none;
}

/* The letterhead: logo above the name, everything centred, address on full width. */
.inv-tpl-receipt .inv-head,
.inv-tpl-restaurant .inv-head {
  display: block;
  text-align: center;
  padding-bottom: 2.5mm;
  margin-bottom: 2.5mm;
}

.inv-tpl-receipt .inv-brand,
.inv-tpl-restaurant .inv-brand {
  display: block;
}

.inv-tpl-receipt .inv-logo,
.inv-tpl-restaurant .inv-logo {
  margin: 0 auto 1.6mm;
}

.inv-tpl-receipt .inv-address,
.inv-tpl-restaurant .inv-address {
  max-width: none;
}

.inv-tpl-receipt .inv-contact,
.inv-tpl-restaurant .inv-contact,
.inv-tpl-receipt .inv-idents,
.inv-tpl-restaurant .inv-idents {
  justify-content: center;
}

.inv-tpl-receipt .inv-doc,
.inv-tpl-restaurant .inv-doc {
  min-width: 0;
  margin-top: 2.5mm;
  text-align: center;
}

.inv-tpl-receipt .inv-composition-note,
.inv-tpl-restaurant .inv-composition-note {
  max-width: none;
}

/* Bill no., date, table, cashier — label left, value right, across the full column.
   That is the block both photographed bills lead with, and it is the one part of a
   restaurant bill a customer reads before the items. */
.inv-tpl-receipt .inv-doc-meta th,
.inv-tpl-restaurant .inv-doc-meta th {
  padding-right: 2mm;
  text-align: left;
}

.inv-tpl-receipt .inv-doc-meta td,
.inv-tpl-restaurant .inv-doc-meta td {
  text-align: right;
}

/* "Name: ____" and the payment line, as lines rather than as two bordered cards. Same
   decision the thermal roll already makes, for the same reason. */
.invoice-sheet.inv-tpl-receipt .inv-parties,
.invoice-sheet.inv-tpl-restaurant .inv-parties {
  grid-template-columns: minmax(0, 1fr);
  gap: 1.4mm;
  margin-bottom: 2.5mm;
}

/* The restaurant bill's labels are written, not shouted — "Name:", "Date:", "Cashier:",
   "Sub Total". The app-wide `th { text-transform: uppercase }` from the base table
   rules reaches every one of them, and all-caps is a ledger convention, not the way a
   bill is read by the person who just ate. The dot-matrix template keeps the caps: that
   printer had no lower case. */
.inv-tpl-restaurant .inv-doc-meta th,
.inv-tpl-restaurant .inv-totals th,
.inv-tpl-restaurant .inv-party h2 {
  color: var(--inv-ink-soft);
  font-weight: 600;
  letter-spacing: 0;
  text-transform: none;
}

.inv-tpl-restaurant .inv-party h2 {
  font-size: 10.5px;
}

.inv-tpl-receipt .inv-party,
.inv-tpl-restaurant .inv-party {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0 2mm;
  padding: 0;
  border: none;
  border-radius: 0;
  background: none;
}

.inv-tpl-receipt .inv-party h2,
.inv-tpl-restaurant .inv-party h2,
.inv-tpl-receipt .inv-party p,
.inv-tpl-restaurant .inv-party p {
  margin: 0;
}

.inv-tpl-receipt .inv-party-name,
.inv-tpl-restaurant .inv-party-name {
  font-size: 11px !important;
}

/* The monogram is our stand-in for a logo the shop never uploaded — a filled accent
   tile, which is the one thing on the page a receipt printer cannot print and a hotel
   bill does not have. A logo the shop DID upload still prints, centred above the name. */
.inv-tpl-receipt .inv-monogram,
.inv-tpl-restaurant .inv-monogram {
  display: none;
}

/* The stamp is rotated 13°, which makes a 22mm box occupy about 30mm — fine in the
   original three-column footer where it had a column to itself, and straight through
   the signature line once the footer is a single centred column. Less tilt, and the
   difference reserved as margin. */
.inv-tpl-receipt .inv-stamp,
.inv-tpl-restaurant .inv-stamp {
  transform: rotate(-6deg);
  margin: 2.5mm 0;
}

/* Items: no filled header band, no zebra. A receipt printer has one colour, and a
   restaurant bill run off a laser still has to read as a receipt. */
.inv-tpl-receipt .inv-items tbody tr:nth-child(even) td,
.inv-tpl-restaurant .inv-items tbody tr:nth-child(even) td {
  background: transparent;
}

.inv-tpl-receipt .inv-items tbody td,
.inv-tpl-restaurant .inv-items tbody td {
  border-bottom: none;
  padding: 1mm 1.6mm;
}

/* The lower half is one column, and the money comes FIRST. On both bills the grand
   total sits directly under the last item; the amount in words, the tax summary and the
   bank block follow it. `order` on a grid item is what puts them in that order without
   a second markup tree. */
.invoice-sheet.inv-tpl-receipt .inv-lower,
.invoice-sheet.inv-tpl-restaurant .inv-lower {
  grid-template-columns: minmax(0, 1fr);
  gap: 2.5mm;
}

.inv-tpl-receipt .inv-lower-right,
.inv-tpl-restaurant .inv-lower-right {
  order: -1;
}

.inv-tpl-receipt .inv-block,
.inv-tpl-restaurant .inv-block {
  padding: 2mm 0 0;
  border: none;
  border-radius: 0;
  margin-bottom: 2.5mm;
}

.inv-tpl-receipt .inv-words,
.inv-tpl-restaurant .inv-words {
  background: none;
}

.inv-tpl-receipt .inv-savings,
.inv-tpl-restaurant .inv-savings {
  background: none;
  padding: 1mm 0 0;
}

/* Foot and thank-you line, centred, in one column. `.inv-foot` is a GRID — a
   flex-direction on it alone does nothing, so the display has to be reset first. */
.inv-tpl-receipt .inv-foot,
.inv-tpl-restaurant .inv-foot {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3mm;
  min-height: 0;
  text-align: center;
}

.inv-tpl-receipt .inv-foot-pay,
.inv-tpl-restaurant .inv-foot-pay {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.5mm;
}

.inv-tpl-receipt .inv-strip,
.inv-tpl-restaurant .inv-strip {
  flex-direction: column;
  align-items: center;
  gap: 0.6mm;
  padding: 2mm 0 0;
  border-radius: 0;
  background: none;
  text-align: center;
  letter-spacing: 0.04em;
}

/* ---- Receipt: the dot-matrix slip ----
   Monospace, because that is what makes it read as a till slip and because 0/O and 1/I
   have to stay apart on cheap paper. Rules are dashed, the way a dot-matrix printer
   draws a run of hyphens. */
.inv-tpl-receipt {
  font-family: ui-monospace, "Courier New", Courier, monospace;
}

.inv-tpl-receipt .inv-shop-name {
  font-size: 16px;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--inv-ink);
}

.inv-tpl-receipt .inv-legal-name,
.inv-tpl-receipt .inv-tagline {
  font-style: normal;
  color: var(--inv-ink-soft);
}

.inv-tpl-receipt .inv-idents span {
  padding: 0;
  border: none;
  border-radius: 0;
  background: none;
}

/* "T A X   I N V O I C E". The letter-spacing adds a trailing gap after the last
   character, which pushes centred text half a space to the left — the matching
   text-indent puts it back. */
.inv-tpl-receipt .inv-doc-type {
  display: block;
  padding: 0;
  border-radius: 0;
  background: none;
  color: var(--inv-ink);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.42em;
  text-indent: 0.42em;
}

.inv-tpl-receipt .inv-head {
  border-bottom: 1px dashed var(--inv-ink-faint);
}

.inv-tpl-receipt .inv-items thead th {
  padding: 1.2mm 1.6mm;
  border-top: 1px dashed var(--inv-ink-faint);
  border-bottom: 1px dashed var(--inv-ink-faint);
  background: transparent;
  color: var(--inv-ink);
  letter-spacing: 0.04em;
}

.inv-tpl-receipt .inv-item-name {
  font-weight: 500;
  text-transform: uppercase;
}

.inv-tpl-receipt .inv-items tfoot td {
  padding: 1.2mm 1.6mm;
  border-top: 1px dashed var(--inv-ink-faint);
  border-bottom: 1px dashed var(--inv-ink-faint);
  background: transparent;
}

.inv-tpl-receipt .inv-totals th,
.inv-tpl-receipt .inv-totals td {
  padding: 0.9mm 1.6mm;
  border-bottom: none;
}

/* The double rule under the total is the row of '=' every dot-matrix bill ends on. */
.inv-tpl-receipt .inv-grand {
  margin-top: 0.5mm;
  padding: 1.4mm 1.6mm;
  border-top: 1px solid var(--inv-ink);
  border-bottom: 3px double var(--inv-ink);
  border-radius: 0;
  background: none;
  color: var(--inv-ink);
}

.inv-tpl-receipt .inv-grand span {
  letter-spacing: 0.06em;
}

.inv-tpl-receipt .inv-grand strong {
  font-size: 17px;
}

.inv-tpl-receipt .inv-block h2,
.inv-tpl-receipt .inv-party h2 {
  color: var(--inv-ink-soft);
}

.inv-tpl-receipt .inv-strip {
  border-top: 1px dashed var(--inv-ink-faint);
  color: var(--inv-ink-soft);
}

/* ---- Restaurant: the printed hotel bill ----
   Bold centred name, solid full-width rules, sentence-case column heads, and one large
   grand total. No dashes anywhere — this is the bill printed on good paper, not the
   canteen slip. */
.inv-tpl-restaurant .inv-shop-name {
  font-size: 22px;
  font-weight: 800;
  letter-spacing: 0.01em;
  color: var(--inv-ink);
}

.inv-tpl-restaurant .inv-address,
.inv-tpl-restaurant .inv-contact {
  font-size: 11px;
}

.inv-tpl-restaurant .inv-idents span {
  padding: 0;
  border: none;
  border-radius: 0;
  background: none;
}

.inv-tpl-restaurant .inv-doc-type {
  display: block;
  padding: 0;
  border-radius: 0;
  background: none;
  color: var(--inv-accent-deep);
  font-size: 11px;
  letter-spacing: 0.22em;
}

.inv-tpl-restaurant .inv-head {
  border-bottom: 1.4px solid var(--inv-ink);
}

.inv-tpl-restaurant .inv-doc-meta th,
.inv-tpl-restaurant .inv-doc-meta td {
  font-size: 11px;
}

/* "Item  Qty.  Price  Amount" — as written, not shouted. The all-caps heading is a
   ledger convention; a restaurant bill is read by the person who just ate. */
.inv-tpl-restaurant .inv-items thead th {
  padding: 1.6mm;
  border-top: 1.4px solid var(--inv-ink);
  border-bottom: 1.4px solid var(--inv-ink);
  background: transparent;
  color: var(--inv-ink);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0;
  text-transform: none;
}

.inv-tpl-restaurant .inv-items tbody td {
  font-size: 11px;
}

.inv-tpl-restaurant .inv-item-name {
  font-weight: 500;
}

.inv-tpl-restaurant .inv-items tfoot td {
  padding: 1.6mm;
  border-top: 1.4px solid var(--inv-ink);
  border-bottom: 1.4px solid var(--inv-ink);
  background: transparent;
}

.inv-tpl-restaurant .inv-totals th,
.inv-tpl-restaurant .inv-totals td {
  padding: 1.1mm 1.6mm;
  font-size: 11px;
  border-bottom: none;
}

.inv-tpl-restaurant .inv-grand {
  margin-top: 0.5mm;
  padding: 1.8mm 1.6mm;
  border-top: 1.4px solid var(--inv-ink);
  border-bottom: 1.4px solid var(--inv-ink);
  border-radius: 0;
  background: none;
  color: var(--inv-ink);
}

.inv-tpl-restaurant .inv-grand span {
  font-size: 13px;
  letter-spacing: 0.02em;
  text-transform: none;
}

.inv-tpl-restaurant .inv-grand strong {
  font-size: 20px;
}

.inv-tpl-restaurant .inv-strip {
  border-top: 1px solid var(--inv-rule-strong);
  color: var(--inv-ink-soft);
  font-size: 11px;
}

/* ---- On a page, a receipt is a narrow centred column ----
   The sheet stays A4/A5 — it has to, it is going into a printer that holds that paper —
   but 186mm of usable width turns a four-line food bill into a mostly-empty table. The
   padding does the centring, so nothing inside has to know about it. */
.inv-paper-a4.inv-tpl-receipt,
.inv-paper-a4.inv-tpl-restaurant {
  padding: 14mm 48mm 12mm;
}

.inv-paper-a5.inv-tpl-receipt,
.inv-paper-a5.inv-tpl-restaurant {
  padding: 10mm 26mm 9mm;
}

/* ==========================================================================
   NEW DOCUMENT PARTS
   ========================================================================== */

/* Hidden except on Modern, which is the only layout that puts the total up top. */
.inv-head-total {
  display: none;
}

/* The line that stops a quotation from being mistaken for a tax invoice. Deliberately
   loud: this is a legal distinction, not a footnote. */
.inv-kind-note {
  margin: 0 0 3mm;
  padding: 1.6mm 3mm;
  border: 1px dashed var(--inv-accent-line);
  border-left: 2.5px solid var(--inv-accent);
  border-radius: 1.5mm;
  background: var(--inv-accent-soft);
  color: var(--inv-accent-dark);
  font-size: 9.5px;
  font-weight: 700;
}

.inv-account .inv-kv th {
  width: 44mm;
}

.inv-account-total th,
.inv-account-total td {
  color: var(--inv-unpaid);
  font-weight: 800;
  border-top: 1px solid var(--inv-rule);
  padding-top: 1mm;
}

.inv-notes p {
  white-space: pre-wrap;
  font-size: 9.5px;
}

.inv-eoe {
  margin: 1.5mm 0 0;
  font-size: 8.5px;
  letter-spacing: 0.06em;
  color: var(--inv-ink-faint);
}

.inv-col-mrp {
  width: 19mm;
  color: var(--inv-ink-soft);
}

.inv-col-disc {
  width: 20mm;
  color: var(--inv-paid);
}

.inv-sign-receiver .inv-sign-line {
  width: 40mm;
}

/* ==========================================================================
   58mm ROLL
   Rides on every .inv-paper-thermal rule (the component adds both classes) and only
   narrows the page — at 58mm even the two-column parties block is one column, which
   the thermal rules already did.
   ========================================================================== */
.inv-paper-thermal58 {
  width: 58mm;
  padding: 4mm 3mm 3mm;
  font-size: 8.5px;
}

.inv-paper-thermal58 .inv-shop-name {
  font-size: 13px;
}

.inv-paper-thermal58 .inv-logo {
  width: 11mm;
  height: 11mm;
}

.inv-paper-thermal58 .inv-doc-type {
  font-size: 10px;
  padding: 0.8mm 2mm;
  letter-spacing: 0.08em;
}

.inv-paper-thermal58 .inv-items thead th,
.inv-paper-thermal58 .inv-items tbody td {
  padding: 0.9mm 0.7mm;
  font-size: 8px;
}

.inv-paper-thermal58 .inv-grand strong {
  font-size: 13px;
}

.inv-paper-thermal58 .inv-stamp-inner {
  width: 32mm;
  height: 18mm;
}

.inv-paper-thermal58 .inv-idents span {
  font-size: 7.5px;
}

/* A roll has no fixed length, so nothing on it should be trying to fill a page. */
.inv-paper-thermal .inv-foot,
.inv-paper-thermal58 .inv-foot {
  min-height: 0;
}

/* ==========================================================================
   RESPONSIVE + PRINT
   ========================================================================== */
@media (max-width: 1080px) {
  .invoice-studio {
    grid-template-columns: minmax(0, 1fr);
  }

  .invoice-controls {
    position: static;
    max-height: none;
    overflow: visible;
  }

  .inv-tpl-grid {
    grid-template-columns: repeat(6, 1fr);
  }
}

@media (max-width: 640px) {
  .inv-tpl-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .invoice-actionbar-doc {
    order: 3;
    flex-basis: 100%;
  }

  .invoice-actionbar-right {
    margin-left: 0;
  }
}

@media (max-width: 900px) {
  /* Inside the studio only. There the sheet is scaled by `zoom` on .invoice-zoom, which
     keeps its own layout height, so the older transform + negative-margin hack would
     double-shrink it and leave a hole under the page. The Settings preview has no zoom
     control and still wants that hack, so it is deliberately left alone. */
  .invoice-zoom .invoice-sheet,
  .invoice-zoom .inv-paper-a5,
  .invoice-zoom .inv-paper-a6,
  .invoice-zoom .inv-paper-thermal {
    transform: none;
    margin-bottom: 0;
  }
}

@media print {
  .invoice-studio {
    display: block;
  }

  .invoice-controls,
  .invoice-actionbar,
  .invoice-zoombar,
  .invoice-sharelink {
    display: none !important;
  }

  /* Beats the inline zoom on .invoice-zoom — an inline style without !important
     loses to an important declaration, which is exactly what is wanted: the preview
     may be at 60%, the paper never is. */
  .invoice-zoom {
    zoom: 1 !important;
    display: block;
  }

  /* Each copy is its own sheet of paper. */
  .invoice-copy {
    break-after: page;
    page-break-after: always;
  }

  .invoice-copy:last-child {
    break-after: auto;
    page-break-after: auto;
  }

  .inv-copy-extra {
    display: block;
  }

  /* Keep the blocks that read as one thing on one page. */
  .inv-kind-note,
  .inv-totals,
  .inv-account,
  .inv-tax-summary {
    break-inside: avoid;
  }
}


/* ==========================================================================
   INVOICE — round 3: the parts each trade's bill is actually kept for
   Serial numbers and warranty dates (electronics, mobile, autoparts), the
   cancelled band, and the credit note's own accents. All ink-on-white, like the
   rest of the sheet.
   ========================================================================== */

/* Serial number and warranty-until, under the item name. Deliberately ink-coloured
   rather than the muted note grey above it: this is not an aside, it is the line a
   warranty claim is refused for want of. Monospace so 0/O and 1/I stay apart on a
   serial number read off a printed page eleven months later. */
.inv-serial {
  color: var(--inv-ink-soft);
  font-family: ui-monospace, 'SF Mono', Menlo, Consolas, monospace;
  letter-spacing: 0.01em;
}

/* A cancelled bill stays printable — a shop needs the cancelled copy for its own file —
   but it can never come out looking live. Band across the top, stamp across the foot. */
.inv-cancel-band {
  margin: 0 0 3mm;
  padding: 1.8mm 3mm;
  border: 1.4px solid var(--inv-unpaid);
  border-radius: 1.5mm;
  background: #fef2f2;
  color: var(--inv-unpaid);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-align: center;
}

.inv-status-cancelled .inv-stamp-inner {
  border-color: var(--inv-unpaid);
  outline-color: var(--inv-unpaid);
  color: var(--inv-unpaid);
}

/* Ink saver strips the red, like every other colour on the page — the band still reads
   as a band because of the rule, not the fill. */
.inv-mono .inv-cancel-band {
  background: #fff;
  border-color: #000;
  color: #000;
}

@media print {
  .inv-cancel-band,
  .inv-serial {
    break-inside: avoid;
  }
}


/* ==========================================================================
   ROLL PAPER — 80mm and 58mm, properly

   A receipt roll is not a small sheet of A4. It is 72mm (or 52mm) of usable width
   with no bottom edge, and every rule written for a page has to be re-decided here.
   The earlier thermal block got the idea right but left four things broken, all of
   which show up as "it doesn't look proper":

     1. `.inv-foot` is a GRID (1fr auto auto). Setting `flex-direction: column` on a
        grid does nothing, so the QR, the stamp and the signature stayed in three
        columns squeezed into 72mm.
     2. The item table's column widths are absolute millimetres — qty 20 + rate 20 +
        amount 24 + sr 7 = 71mm of a 72mm row, leaving the item name about one
        millimetre and wrapping every product name one letter per line.
     3. The MRP and Discount columns added later were never added to the hide list,
        so on a roll they pushed the table wider than the paper — and the sheet is
        `overflow: hidden`, so it clipped rather than scrolled.
     4. The six templates apply page layouts (a 40mm letterhead gap, padded header
        panels, full box grids) that are meaningless on a roll.

   Everything below is keyed on `.inv-paper-thermal`, which the 58mm roll also wears,
   so both sizes inherit one set of decisions and only the tight spots are re-tuned
   for 58mm further down.
   ========================================================================== */

/* ---- 1. Columns a roll cannot afford ---- */
.inv-paper-thermal .inv-col-mrp,
.inv-paper-thermal .inv-col-disc {
  display: none;
}

/* ---- 2. The item table, in proportions instead of millimetres ----
   `table-layout: fixed` is what makes the percentages binding; without it the browser
   still negotiates widths from the content and a long product name wins every time.
   The five visible columns add up to 100, so the same rule works at 80mm and 58mm. */
.inv-paper-thermal .inv-items {
  table-layout: fixed;
  width: 100%;
}

/* The split is money-first. A rupee figure must never wrap — "₹1,299.00" broken across
   two lines is the one thing on a receipt a customer will query — so rate and amount are
   sized to hold five digits plus paise at the smallest font on the narrowest roll, and
   the item name takes what is left and wraps, which is what a product name is allowed to
   do. At 58mm that leaves ~12.5mm for the amount and ~18.7mm for the name. */
.inv-paper-thermal .inv-col-sr {
  width: 6%;
}

.inv-paper-thermal .inv-col-item {
  width: 36%;
  /* `break-word` only splits a word that cannot fit on a line of its own, which is the
     one case where splitting beats overflowing. */
  overflow-wrap: break-word;
}

.inv-paper-thermal .inv-col-qty {
  width: 14%;
  /* The unit rides as an inline span after the number; letting the cell wrap puts it on
     its own line instead of widening the column. */
  white-space: normal;
}

.inv-paper-thermal .inv-col-rate {
  width: 20%;
}

.inv-paper-thermal .inv-col-amount {
  width: 24%;
}

.inv-paper-thermal .inv-item-name {
  font-size: 9px;
  line-height: 1.25;
}

.inv-paper-thermal .inv-item-note {
  font-size: 7.5px;
  line-height: 1.25;
}

.inv-paper-thermal .inv-unit {
  font-size: 7.5px;
}

/* ---- 3. The footer, which was never actually stacking ---- */
.inv-paper-thermal .inv-foot {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 2.5mm;
  min-height: 0;
  padding-top: 2.5mm;
}

.inv-paper-thermal .inv-foot-pay {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.5mm;
  width: 100%;
}

/* The QR and its caption sat side by side: a 104px code is ~27mm, the caption another
   26mm, and at 58mm that is already wider than the paper. Stacked, both fit at either
   size and the caption can use the full width. */
.inv-paper-thermal .inv-qr {
  flex-direction: column;
  gap: 1.5mm;
}

.inv-paper-thermal .inv-qr span {
  max-width: none;
  text-align: center;
}

.inv-paper-thermal .inv-sign {
  width: 100%;
  min-width: 0;
}

.inv-paper-thermal .inv-sign-space {
  height: 12mm;
}

.inv-paper-thermal .inv-sign-line {
  width: 80%;
}

.inv-paper-thermal .inv-eoe {
  text-align: center;
}

/* ---- 4. Blocks that assume a page ---- */
.inv-paper-thermal .inv-lower {
  gap: 2.5mm;
  margin-bottom: 2.5mm;
}

.inv-paper-thermal .inv-block {
  margin-bottom: 2mm;
  padding: 1.6mm 2mm;
}

.inv-paper-thermal .inv-party {
  padding: 1.6mm 2mm;
  text-align: left;
}

.inv-paper-thermal .inv-parties {
  gap: 2mm;
  margin-bottom: 2.5mm;
}

/* Rate-wise GST on a roll: five bordered columns at 72mm are unreadable, so it drops
   to the smallest legible size rather than being hidden — a chemist's or a hardware
   shop's customer does ask for the tax split, even on a receipt. */
.inv-paper-thermal .inv-tax-summary th,
.inv-paper-thermal .inv-tax-summary td {
  padding: 0.8mm 0.8mm;
  font-size: 7.5px;
}

.inv-paper-thermal .inv-totals th,
.inv-paper-thermal .inv-totals td {
  padding: 0.9mm 0;
  font-size: 9px;
}

.inv-paper-thermal .inv-grand {
  padding: 1.8mm 2mm;
}

.inv-paper-thermal .inv-grand span {
  font-size: 8.5px;
  letter-spacing: 0.06em;
}

/* Two spans pushed to opposite ends of 72mm collide. On a roll the strip reads as two
   centred lines, which is how every receipt in the country ends. */
.inv-paper-thermal .inv-strip {
  flex-direction: column;
  gap: 0.8mm;
  text-align: center;
  padding: 1.5mm 2mm;
  font-size: 8px;
}

.inv-paper-thermal .inv-idents {
  gap: 1mm;
}

.inv-paper-thermal .inv-idents span {
  font-size: 7.5px;
  padding: 0.3mm 1.2mm;
}

.inv-paper-thermal .inv-contact {
  gap: 0 2mm;
  font-size: 8px;
}

.inv-paper-thermal .inv-doc-meta th,
.inv-paper-thermal .inv-doc-meta td {
  padding: 0.5mm 0;
  font-size: 8.5px;
}

.inv-paper-thermal .inv-kind-note,
.inv-paper-thermal .inv-cancel-band {
  font-size: 8px;
  padding: 1.2mm 2mm;
  margin-bottom: 2mm;
}

/* ---- 5. Templates are page layouts; a roll has exactly one ----
   The accent colour, the ink saver and the density still apply — those are about
   *how it prints*, which matters as much on a roll as on a page. What is neutralised
   here is only the geometry. */
.inv-paper-thermal.inv-tpl-letterhead {
  padding-top: 5mm;
}

/* Nobody buys pre-printed 80mm rolls, so the letterhead comes back and the template
   behaves like Classic. */
.inv-paper-thermal.inv-tpl-letterhead .inv-brand {
  display: flex;
}

.inv-paper-thermal.inv-tpl-letterhead .inv-ribbon {
  display: block;
}

.inv-paper-thermal.inv-tpl-letterhead .inv-head {
  justify-content: flex-start;
}

.inv-paper-thermal.inv-tpl-modern {
  padding-top: 5mm;
}

.inv-paper-thermal.inv-tpl-modern .inv-head {
  padding: 0 0 2.5mm;
  background: transparent;
  border-radius: 0;
  border-bottom: 1.5px solid var(--inv-accent);
}

.inv-paper-thermal.inv-tpl-tally {
  padding: 5mm 4mm 4mm;
}

