.inv-paper-thermal.inv-tpl-restaurant .inv-address,
.inv-paper-thermal.inv-tpl-restaurant .inv-contact,
.inv-paper-thermal.inv-tpl-restaurant .inv-doc-meta th,
.inv-paper-thermal.inv-tpl-restaurant .inv-doc-meta td,
.inv-paper-thermal.inv-tpl-restaurant .inv-items thead th,
.inv-paper-thermal.inv-tpl-restaurant .inv-items tbody td,
.inv-paper-thermal.inv-tpl-restaurant .inv-totals th,
.inv-paper-thermal.inv-tpl-restaurant .inv-totals td,
