}

.inv-paper-thermal.inv-tpl-receipt .inv-items thead th,
.inv-paper-thermal.inv-tpl-receipt .inv-items tfoot td,
.inv-paper-thermal.inv-tpl-restaurant .inv-items thead th,
.inv-paper-thermal.inv-tpl-restaurant .inv-items tfoot td {
  padding: 1mm 0.8mm;
}

.inv-paper-thermal.inv-tpl-receipt .inv-totals th,
.inv-paper-thermal.inv-tpl-receipt .inv-totals td,
.inv-paper-thermal.inv-tpl-restaurant .inv-totals th,
.inv-paper-thermal.inv-tpl-restaurant .inv-totals td {
  padding: 0.6mm 0.8mm;
}

.inv-paper-thermal.inv-tpl-receipt .inv-grand,
.inv-paper-thermal.inv-tpl-restaurant .inv-grand {
  padding: 1.2mm 0.8mm;
}

.inv-paper-thermal58.inv-tpl-receipt .inv-shop-name,
.inv-paper-thermal58.inv-tpl-restaurant .inv-shop-name {
  font-size: 13px;
}

.inv-paper-thermal58.inv-tpl-restaurant .inv-items thead th,
