}

/* The batch line is monospace and long ("Batch A2214B · Exp 06/28"). At 52mm it needs
   to be allowed to wrap rather than push the column. */
.inv-paper-thermal58 .inv-batch {
  overflow-wrap: break-word;
}

.inv-paper-thermal58 .inv-totals th,
.inv-paper-thermal58 .inv-totals td {
  font-size: 8px;
}

.inv-paper-thermal58 .inv-tax-summary th,
.inv-paper-thermal58 .inv-tax-summary td {
  padding: 0.6mm 0.5mm;
  font-size: 6.5px;
}

.inv-paper-thermal58 .inv-grand span {
