  letter-spacing: 0.02em;
}

.inv-paper-thermal58 .inv-doc-meta th,
.inv-paper-thermal58 .inv-doc-meta td {
  font-size: 7.5px;
}

.inv-paper-thermal58 .inv-contact,
.inv-paper-thermal58 .inv-strip {
  font-size: 7.5px;
}

/* A 40mm stamp rotated inside 52mm clips its own corners against the sheet's
   `overflow: hidden`. Smaller, and barely rotated. */
.inv-paper-thermal58 .inv-stamp {
  transform: rotate(-4deg);
}

.inv-paper-thermal58 .inv-stamp-text {
  font-size: 13px;
  letter-spacing: 0.1em;
}

.inv-paper-thermal58 .inv-stamp-shop {
  max-width: 28mm;
}

.inv-paper-thermal58 .inv-sign-space {
  height: 10mm;
}

.inv-paper-thermal58 .inv-sign-space img {
  max-width: 40mm;
}

