}

.lhm-summary {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(9rem, 1fr));
  gap: 0.5rem;
  margin-bottom: 0.9rem;
}

.lhm-stat {
  display: flex;
  flex-direction: column;
  gap: 0.1rem;
  min-width: 0;
  padding: 0.55rem 0.75rem;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--surface);
}

.lhm-stat > span {
  font-size: var(--fs-2xs);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-muted);
}

.lhm-stat > strong {
  font-size: var(--fs-md);
  font-variant-numeric: tabular-nums;
  overflow-wrap: anywhere;
}

.lhm-stat.is-credit > strong { color: var(--text-danger); }
.lhm-stat.is-payment > strong { color: var(--text-success); }

.lhm-day td {
  padding-block: 0.35rem;
  background: var(--surface-strong);
  font-size: var(--fs-2xs);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-muted);
}

.lhm-entry {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.3rem 0.55rem;
  min-width: 0;
}

.lhm-entry-text {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.lhm-entry-text strong {
  font-size: var(--fs-sm);
}

.lhm-entry-meta {
  font-size: var(--fs-xs);
  color: var(--text-muted);
}

.lhm-credit {
  color: var(--text-danger);
  font-weight: 600;
}

.lhm-paid {
  color: var(--text-success);
  font-weight: 600;
}

.lhm-bal {
  font-weight: 700;
}

.lhm-note .badge {
  margin-left: 0.35rem;
}

.lhm-bill-link {
  font-size: var(--fs-xs);
  font-weight: 600;
  color: var(--brand-text);
  text-decoration: none;
  white-space: nowrap;
}

.lhm-bill-link:hover {
  text-decoration: underline;
}

.lhm-table.is-loading,
.lhm-cards.is-loading {
  opacity: 0.55;
}

.lhm-day-head {
  padding: 0.55rem 0 0.2rem;
  border-bottom: 1px solid var(--border);
  font-size: var(--fs-2xs);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-muted);
}

/* Desktop: one scroll (the dialog body), not a table scroller nested inside it, and the
   column heads stay put while the rows move under them. */
@media (min-width: 901px) {
  .ledger-history-modal .table-wrap {
    max-height: none;
    overflow: visible;
  }

  .ledger-history-modal .data-table thead th {
    position: sticky;
    top: 0;
    z-index: 2;
    background: var(--bg-elevated, var(--surface));
  }
}

@media (max-width: 640px) {
  .lhm-toolbar .segmented-mini {
    width: 100%;
    height: auto;
  }

  /* Sized to their words, never broken inside them: "Payment / received" on two lines
     read as two buttons. */
  .lhm-toolbar .segmented-mini button {
    flex: 1 1 auto;
    justify-content: center;
    padding: 0.4rem 0.45rem;
    white-space: nowrap;
  }

  /* One swipeable line of range chips instead of two wrapped rows. `min-width: 0` so the
     scroller cannot widen its flex parent (see the range-filter phone fix). */
  .lhm-ranges {
    flex-basis: 100%;
    min-width: 0;
    flex-wrap: nowrap;
    overflow-x: auto;
    scrollbar-width: none;
  }

  .lhm-ranges::-webkit-scrollbar {
    display: none;
  }

  .lhm-ranges > .chip {
    flex-shrink: 0;
  }

  .lhm-summary {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}


/* ---------- Admin revenue board (/admin/revenue) ----------
   Only new selectors, appended after every responsive block, so nothing above can be
   overridden by accident. The board itself is the shared viz kit; these are its seams. */
.rev-filter-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.6rem;
  margin-bottom: 1rem;
}
.rev-filter-tools { display: flex; align-items: center; gap: 0.35rem; margin-left: auto; }
.rev-updated { font-size: var(--fs-xs); color: var(--text-faint); margin-right: 0.25rem; }

/* How far through the month the hero's number is — the projection is only honest next to it. */
.rev-month-track {
  max-width: 320px;
  height: 4px;
  margin-top: 0.6rem;
  border-radius: var(--radius-full);
  background: var(--surface-strong);
  overflow: hidden;
}
.rev-month-track span { display: block; height: 100%; border-radius: inherit; background: var(--success); }

.viz-tip-total { margin-top: 0.1rem; padding-top: 0.2rem; border-top: 1px solid var(--border); }

.rev-grid { margin-bottom: 1rem; }
.rev-split-gap { height: 1rem; }
.rev-insight { cursor: default; }

.rev-ring-row { display: flex; align-items: center; flex-wrap: wrap; gap: 1.1rem; padding-top: 0.3rem; }
.rev-ring-facts { flex: 1 1 150px; margin-top: 0; padding-top: 0; border-top: 0; }

.rev-hint { text-align: left; padding: 0 0 0.6rem; }
.rev-panel-total { font-size: var(--fs-sm); font-weight: 650; color: var(--text); font-variant-numeric: tabular-nums; }
.rev-payments-head { flex-wrap: wrap; gap: 0.6rem; }
.rev-count { font-size: var(--fs-2xs); color: var(--text-faint); font-variant-numeric: tabular-nums; }
.segmented button.active .rev-count { color: var(--text-muted); }

.rev-kind {
  display: inline-block;
  margin-top: 0.2rem;
  padding: 0.05rem 0.4rem;
  border-radius: var(--radius-full);
  font-size: var(--fs-2xs);
  font-weight: 650;
}
.rev-kind-new { color: var(--text-success); background: rgba(52, 211, 153, 0.14); }
.rev-kind-renewal { color: var(--brand-text); background: rgba(var(--brand-rgb), 0.12); }

.rev-bar-cell { min-width: 150px; }
.rev-bar-cell strong { display: block; margin-bottom: 0.3rem; }
.rev-bar-cell .breakdown-track { display: block; height: 6px; }
.rev-bar-cell .breakdown-fill { display: block; height: 100%; }

@media (max-width: 560px) {
  .rev-filter-tools { margin-left: 0; }
  .rev-updated { display: none; }
  .rev-ring-row { justify-content: center; }
}


/* ---------- Admin revenue: period picker, tabs, VIP, cohorts ---------- */
.rev-period {
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
  margin-bottom: 0.9rem;
  padding: 0.8rem 0.9rem;
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  background: var(--bg-elevated);
  min-width: 0;
}
.rev-period-row { display: flex; align-items: center; flex-wrap: wrap; gap: 0.5rem; min-width: 0; }
.rev-period-row .filter-select { min-width: 140px; }
.rev-period-tools { display: flex; align-items: center; gap: 0.35rem; margin-left: auto; }
.rev-period-label { display: flex; flex-wrap: wrap; align-items: baseline; gap: 0.25rem 0.6rem; margin: 0; font-size: var(--fs-sm); color: var(--text-muted); }
.rev-period-label strong { color: var(--text); font-size: var(--fs-md); }

.rev-tabs { display: inline-grid; grid-auto-flow: column; grid-template-columns: none; margin-bottom: 1rem; max-width: 100%; overflow-x: auto; }
.rev-tabs button { padding-inline: 1rem; }
.rev-tab-alert {
  min-width: 1.15rem;
  padding: 0 0.3rem;
  border-radius: var(--radius-full);
  background: var(--danger);
  color: #fff;
  font-size: var(--fs-2xs);
  line-height: 1.15rem;
  text-align: center;
}

.rev-explain { display: flex; align-items: flex-start; gap: 0.45rem; margin-bottom: 1rem; }
.rev-explain svg { flex: none; margin-top: 0.15rem; }

.rev-tier {
  display: inline-flex;
  align-items: center;
  gap: 0.2rem;
  padding: 0.1rem 0.5rem;
  border-radius: var(--radius-full);
  font-size: var(--fs-xs);
  font-weight: 700;
  white-space: nowrap;
}
.rev-tier-vip { color: var(--text-warning); background: rgba(251, 191, 36, 0.18); }
.rev-tier-loyal { color: var(--brand-text); background: rgba(var(--brand-rgb), 0.12); }
.rev-tier-regular { color: var(--text-muted); background: var(--surface-strong); }
.rev-row-risk td:first-child { box-shadow: inset 3px 0 0 var(--danger); }

.rev-kind-upgrade { color: var(--text); background: rgba(144, 133, 233, 0.2); }
.rev-kind-downgrade { color: var(--text-warning); background: rgba(251, 191, 36, 0.14); }

.rev-pay-tools { display: flex; align-items: center; flex-wrap: wrap; gap: 0.5rem; }
.rev-pay-summary { margin: 0 0 0.6rem; font-size: var(--fs-sm); color: var(--text-muted); }
.rev-facts-top { margin-top: 0; padding-top: 0.2rem; border-top: 0; }

.rev-heat {
  display: inline-block;
  min-width: 3.2rem;
  padding: 0.15rem 0.4rem;
  border-radius: var(--radius-sm, 6px);
  background: rgba(27, 175, 122, var(--heat-i, 0.2));
  color: var(--text);
  font-weight: 650;
}
.rev-bar-cell .cell-sub { display: block; margin-top: 0.2rem; }

@media (max-width: 560px) {
  .rev-period { padding: 0.7rem; }
  .rev-period-row .filter-select { flex: 1 1 130px; min-width: 0; }
  .rev-period-tools { margin-left: 0; }
  .rev-tabs { display: grid; grid-auto-flow: row; grid-template-columns: 1fr 1fr; width: 100%; }
  .rev-pay-tools, .rev-pay-tools .search-box-inline { width: 100%; }
}


/* ---------- Admin cost & usage (/admin/usage) ----------
   Appended last, after every responsive block, so nothing above can be overridden by
   accident. The board itself is the shared viz kit and the period bar is the revenue
   screen's; these are the seams this page adds. */

/* The rates every figure on the page is multiplied by, stated where they are used rather
   than left on a settings screen the operator has to trust from memory. A button, because
   reading them and changing them are the same gesture. */
.usg-rate-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  min-width: 0;
  height: var(--filter-h, 2.2rem);
  padding: 0 0.7rem;
  border: 1px solid var(--border);
  border-radius: var(--radius-full);
  background: var(--surface-strong);
  color: var(--text-muted);
  font-size: var(--fs-xs);
  font-variant-numeric: tabular-nums;
  cursor: pointer;
}

.usg-rate-chip:hover {
  border-color: rgba(var(--brand-rgb), 0.45);
  color: var(--text);
}

.usg-rate-chip > span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.usg-rate-chip em {
  flex: none;
  color: var(--brand-text);
  font-style: normal;
  font-weight: 650;
}

/* Money the platform is down on. One class, used on hero figures, table cells and the
   blocked count alike, so "we are losing on this" reads the same everywhere. */
.usg-neg,
.viz-hero-figure strong.usg-neg {
  color: var(--text-danger);
}

/* ---------- a shop's three quotas, as three bars ---------- */

.usg-meters {
  display: grid;
  gap: 0.4rem;
  min-width: 190px;
}

.usg-meter {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 0.15rem;
}

/* Name and number share a line, bar underneath: three meters stacked as three lines each
   made every shop row nine lines tall, which is a scroll, not a table. */
.usg-meter-top {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.5rem;
}

.usg-meter-name {
  font-size: var(--fs-2xs);
  color: var(--text-muted);
  white-space: nowrap;
}

.usg-meter-track {
  display: block;
  height: 5px;
  border-radius: var(--radius-full);
  background: var(--surface-strong);
  overflow: hidden;
}

.usg-meter-track > .breakdown-fill {
  display: block;
  height: 100%;
  border-radius: inherit;
}

.usg-meter-value {
  display: flex;
  align-items: baseline;
  gap: 0.35rem;
  flex: none;
  font-size: var(--fs-2xs);
  color: var(--text);
}

.usg-meter-value em {
  font-style: normal;
  font-weight: 650;
}

/* The bars are the reason this column reads at a glance; below this they would be slivers,
   so the cell keeps its own floor rather than letting the table squeeze it. */
.usg-meters-col {
  min-width: 210px;
}

/* ---------- one plan tier, priced against its own quotas ---------- */

.usg-plan-head {
  align-items: flex-start;
  flex-wrap: wrap;
  gap: 0.6rem;
}

.usg-plan-head h2 {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.usg-plan-price {
  font-size: var(--fs-sm);
  font-weight: 650;
  color: var(--text-muted);
  font-variant-numeric: tabular-nums;
}

.usg-plan-head .cell-sub {
  margin-top: 0.2rem;
}

.usg-plan-figures {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 0.6rem;
  margin: 0.8rem 0;
}

.usg-figure {
  padding: 0.6rem 0.7rem;
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  background: var(--bg-elevated);
}

/* The tier is exposed to more spend than it charges for, or somebody on it is already
   being refused. Marked on the figure itself so the finding survives being skimmed. */
.usg-figure.is-risky {
  border-color: rgba(220, 38, 38, 0.35);
  background: rgba(220, 38, 38, 0.06);
}

.usg-figure span {
  display: block;
  font-size: var(--fs-2xs);
  color: var(--text-muted);
}

.usg-figure strong {
  display: block;
  margin-top: 0.15rem;
  font-size: var(--fs-lg, 1.1rem);
  font-variant-numeric: tabular-nums;
}

.usg-figure.is-risky strong {
  color: var(--text-danger);
}

.usg-figure em {
  display: block;
  margin-top: 0.15rem;
  font-size: var(--fs-2xs);
  font-style: normal;
  color: var(--text-faint);
}

.usg-plan + .usg-plan {
  margin-top: 1rem;
}

/* ---------- one word for a module's state ---------- */

.usg-state {
  display: inline-flex;
  align-items: center;
  padding: 0.1rem 0.5rem;
  border-radius: var(--radius-full);
  font-size: var(--fs-2xs);
  font-weight: 700;
  white-space: nowrap;
}

.usg-state-danger { color: var(--text-danger); background: rgba(220, 38, 38, 0.14); }
.usg-state-warn { color: var(--text-warning); background: rgba(251, 191, 36, 0.16); }
.usg-state-good { color: var(--text-success); background: rgba(52, 211, 153, 0.14); }
.usg-state-muted { color: var(--text-faint); background: var(--surface-strong); }

@media (max-width: 560px) {
  /* The rate chip is the widest thing in the period row and the least urgent; it drops to
     its own line rather than pushing the month picker into a two-character sliver. */
  .usg-rate-chip {
    flex: 1 1 100%;
    justify-content: flex-start;
  }

  .usg-plan-figures {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .usg-plan-head .btn {
    width: 100%;
    justify-content: center;
  }
}

/* `.viz-tiles` is auto-FILL, which reserves a column even when there is no tile for it —
   four tiles in a five-column grid were squeezed until "▼ 25% vs last month" broke between
   the arrow and the number. auto-fit collapses the empty track instead. */
.usg-tiles {
  grid-template-columns: repeat(auto-fit, minmax(168px, 1fr));
}

/* A breakdown bar inside a table cell stretches to the column, which leaves its percentage
   stranded at the far edge reading as an unrelated number. Capped so the two stay a pair. */
.usg-bar {
  max-width: 190px;
}

/* Excel processing: real counts, with an indeterminate light trail. */
.imp-live-panel { margin-top: 1rem; padding: 1rem; border: 1px solid rgba(var(--brand-rgb), .25); border-radius: 16px; background: linear-gradient(135deg, rgba(var(--brand-rgb), .09), transparent 75%); overflow: hidden; }
.imp-live-heading { display: flex; align-items: center; gap: .5rem; color: var(--text); font-size: var(--fs-sm); font-weight: 650; }
.imp-spark { color: var(--brand); font-size: 1.4rem; animation: imp-sparkle 2.4s ease-in-out infinite; }
.imp-live-dots { display: flex; gap: 4px; margin-left: auto; }
.imp-live-dots i { width: 4px; height: 4px; border-radius: 50%; background: var(--brand); animation: imp-sparkle 1.5s ease-in-out infinite; }
.imp-live-dots i:nth-child(2) { animation-delay: .2s; }
.imp-live-dots i:nth-child(3) { animation-delay: .4s; }
.imp-live-counts { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: .65rem; margin: 1rem 0; }
.imp-live-counts div { min-width: 0; }
.imp-live-counts dt { color: var(--text-muted); font-size: var(--fs-xs); overflow-wrap: anywhere; }
.imp-live-counts dd { margin: .3rem 0 0; color: var(--text); font-size: clamp(1.05rem, 4vw, 1.5rem); font-weight: 750; font-variant-numeric: tabular-nums; }
.imp-live-caption { margin: 0; font-size: var(--fs-xs); color: var(--text-muted); line-height: 1.5; }
.imp-live-panel .imp-bar { height: 8px; }
.imp-live-panel .imp-bar > span { background: linear-gradient(90deg, transparent, var(--brand) 45%, var(--text) 100%); box-shadow: 0 0 12px rgba(var(--brand-rgb), .5); animation-duration: 2.2s; }
@keyframes imp-sparkle { 0%, 100% { opacity: .45; transform: scale(.85); } 50% { opacity: 1; transform: scale(1.1); } }
:root[data-motion='off'] .imp-spark, :root[data-motion='off'] .imp-live-dots i { animation: none; }
@media (prefers-reduced-motion: reduce) {
  :root:not([data-motion='full']) .imp-spark, :root:not([data-motion='full']) .imp-live-dots i { animation: none; }
}

/* Import choices explain their effects on touch screens as well as on hover. */
.import-review-actions { width: 100%; min-width: 0; display: grid; gap: .85rem; text-align: start; }
.import-review-intro { margin: 0; color: var(--text-muted); font-size: var(--fs-sm); line-height: 1.5; }
.import-review-choice { min-width: 0; display: grid; gap: .35rem; }
.import-review-choice .btn { width: 100%; white-space: normal; height: auto; min-height: 42px; }
.import-review-choice p { margin: 0; color: var(--text-muted); font-size: var(--fs-xs); line-height: 1.5; overflow-wrap: anywhere; }

/* The import review fits its content instead of creating a nested scroll area.
   Very short viewports can scroll the overlay, keeping all text reachable. */
.modal-card.modal-fit.import-modal--review {
  position: relative;
  flex: 0 0 auto;
  max-height: none;
  overflow: visible;
  --modal-pad-x: 1.15rem;
  --modal-pad-y: 1rem;
  padding: var(--modal-pad-y) var(--modal-pad-x);
}
.modal-card.modal-fit.import-modal--review .modal-header {
  position: absolute;
  top: .65rem;
  right: .65rem;
  margin: 0;
  padding: 0;
  z-index: 1;
}
.modal-card.modal-fit.import-modal--review .modal-body {
  flex: 0 0 auto;
  overflow: visible;
  padding-bottom: .8rem;
}
.import-modal--review .imp-head { padding-right: 2.5rem; }
.import-modal--review .imp-title { font-size: 1.05rem; line-height: 1.3; }
.import-modal--review .imp-file { margin-top: .2rem; }
.import-modal--review .imp-tally { margin-top: .7rem; gap: .6rem; }
.import-modal--review .imp-tally li { padding: .5rem .65rem; }
.import-modal--review .imp-note { margin-top: .6rem; line-height: 1.4; }
.import-modal--review .import-review-actions { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .6rem .85rem; }
.import-modal--review .import-review-intro { grid-column: 1 / -1; font-size: var(--fs-xs); line-height: 1.35; }
.import-modal--review .import-review-choice { grid-template-rows: auto 1fr; align-content: start; }
.import-modal--review .import-review-choice .btn { font-size: var(--fs-sm); padding: .55rem .65rem; }
.import-modal--review .import-review-choice p { line-height: 1.35; }
.modal-card.modal-fit.import-modal--review .modal-actions { padding-top: .65rem; padding-bottom: .75rem; }
@media (max-width: 420px) {
  .modal-card.modal-fit.import-modal--review { --modal-pad-x: .85rem; --modal-pad-y: .85rem; }
  .import-modal--review .import-review-actions { gap: .55rem; }
  .import-modal--review .imp-head { gap: .5rem; }
  .import-modal--review .imp-mark { width: 34px; height: 34px; flex-shrink: 0; }
  .import-modal--review .imp-tally li { padding: .45rem .5rem; }
}

.imp-stock-choice { display: grid; gap: .3rem; margin-top: .65rem; color: var(--text); font-size: var(--fs-sm); }
.imp-stock-choice select { width: 100%; min-width: 0; padding: .5rem; border: 1px solid var(--border); border-radius: var(--radius-sm); color: var(--text); background: var(--bg-elevated); }
.imp-stock-choice small { color: var(--text-muted); line-height: 1.4; }
.imp-review-errors { margin-top: .65rem; font-size: var(--fs-sm); }
.imp-review-errors summary { cursor: pointer; }

/* Content-sized import dialog with a stable width and top anchor. */
.modal-card.modal-fit.import-modal {
  position: relative;
  flex: 0 0 auto;
  height: auto;
  max-height: calc(100dvh - var(--ov-top, 3.5rem) - var(--ov-bottom, 2rem));
  min-width: 0;
  overflow: hidden;
  --modal-pad-x: 1.25rem;
  --modal-pad-y: 1.25rem;
  padding: var(--modal-pad-y) var(--modal-pad-x);
  background: var(--surface-card);
  animation: none;
  transition: none;
  transform: none;
}
.modal-card.modal-fit.import-modal .modal-body {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  scrollbar-gutter: stable;
  padding-bottom: 1rem;
}
.modal-card.modal-fit.import-modal--run .modal-header {
  position: absolute;
  top: .75rem;
  right: .75rem;
  margin: 0;
  padding: 0;
  z-index: 1;
}
.import-modal--run .imp-head { padding-right: 2.5rem; }
